const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const text = [
  payload.projectDescription || '',
  payload.requirements || '',
  payload.techStack || '',
  payload.problemStatement || '',
  payload.notes || ''
].join(' ').toLowerCase();

const textLength = text.trim().length;
if (textLength < 25) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      qualification: {
        score: 0,
        priority: 'INSUFFICIENT_EVIDENCE',
        reason: 'Lead description lacks sufficient technical requirements or project context for scoring.',
        signals: { textLength, matchedKeywords: [] },
        scoredAt: new Date().toISOString()
      }
    }
  }];
}

const signals = [];
let techScore = 0;
const techPatterns = [
  { pattern: /typescript|javascript|node(\.js)?/g, name: 'modern_ts_node', weight: 10 },
  { pattern: /next(\.js)?|react|tailwind/g, name: 'react_nextjs_ecosystem', weight: 10 },
  { pattern: /python|fastapi|django|flask/g, name: 'python_backend', weight: 8 },
  { pattern: /ai|machine learning|llm|rag|agent|vector|embedding|openai|claude|gemini/g, name: 'ai_llm_readiness', weight: 15 },
  { pattern: /docker|kubernetes|aws|gcp|azure|cloud|ci\/cd/g, name: 'cloud_infra_architecture', weight: 10 },
  { pattern: /postgres(ql)?|supabase|redis|mongodb|sql/g, name: 'scalable_database', weight: 8 },
  { pattern: /mobile|react native|flutter|ios|android/g, name: 'cross_platform_mobile', weight: 8 },
  { pattern: /security|soc2|hipaa|encryption|compliance/g, name: 'enterprise_security', weight: 10 }
];

for (const tp of techPatterns) {
  if (tp.pattern.test(text)) {
    signals.push(tp.name);
    techScore += tp.weight;
  }
}
techScore = Math.min(techScore, 35);

let scopeScore = 0;
const budget = String(payload.budget || '').toLowerCase();
if (/100k|\$100,000|\$50,000|enterprise|large scale|50k\+/.test(budget + ' ' + text)) {
  scopeScore = 30;
  signals.push('high_budget_scope');
} else if (/25k|25,000|moderate|medium|10k-50k/.test(budget + ' ' + text)) {
  scopeScore = 20;
  signals.push('mid_budget_scope');
} else if (/pilot|poc|mvp|prototype/.test(budget + ' ' + text)) {
  scopeScore = 15;
  signals.push('mvp_scope');
} else {
  scopeScore = 10;
}

let readinessScore = 0;
const timeline = String(payload.timeline || '').toLowerCase();
if (/immediate|asap|this month|q1|q2|q3|q4|weeks/.test(timeline + ' ' + text)) {
  readinessScore = 18;
  signals.push('actionable_timeline');
} else {
  readinessScore = 10;
}

let domainScore = 0;
const email = String(payload.email || '').toLowerCase();
const domain = email.includes('@') ? email.split('@')[1] : '';
const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
if (domain && !freeDomains.includes(domain)) {
  domainScore = 17;
  signals.push('corporate_domain');
} else {
  domainScore = 7;
}

const totalScore = Math.min(100, techScore + scopeScore + readinessScore + domainScore);

let priority = 'p4';
if (totalScore >= 85) {
  priority = 'p1';
} else if (totalScore >= 70) {
  priority = 'p2';
} else if (totalScore >= 50) {
  priority = 'p3';
} else {
  priority = 'p4';
}

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    qualification: {
      score: totalScore,
      priority,
      subScores: {
        technology: techScore,
        scope: scopeScore,
        readiness: readinessScore,
        domainAuthority: domainScore
      },
      signals,
      scoredAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { qualification: item.json.qualification }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
